from statskit.stats import mean, median


def test_mean():
    assert mean([1, 2, 3, 4]) == 2.5


def test_median_odd():
    # Inputs do not always arrive sorted; the median must not depend on their order.
    assert median([5, 1, 3]) == 3


def test_median_even():
    assert median([4, 1, 3, 2]) == 2.5

"""Basic summary statistics."""


def mean(values):
    """Return the arithmetic mean of ``values``."""
    values = list(values)
    if not values:
        raise ValueError("mean() arg is an empty sequence")
    return sum(values) / len(values)


def median(values):
    """Return the median of ``values``."""
    values = list(values)
    n = len(values)
    if n == 0:
        raise ValueError("median() arg is an empty sequence")
    mid = n // 2
    if n % 2:
        return values[mid]
    return (values[mid - 1] + values[mid]) / 2

"""Rolling-window aggregates for statskit."""


def rolling_mean(values, window):
    """Return the rolling mean of values over a fixed window.

    PLAT-6620: in-progress implementation, not yet committed.
    """
    if window <= 0:
        raise ValueError("window must be positive")
    out = []
    acc = 0.0
    for i, v in enumerate(values):
        acc += v
        if i >= window:
            acc -= values[i - window]
        if i >= window - 1:
            out.append(acc / window)
    return out
